-- Agency sources for Trends & Intelligence. Safe to run again: it updates by name. Chosen 22 Nov 2026 for social media, branding,
-- OOH, paid media and lead generation, AI in marketing, and Gulf marketing. autoApprove means headlines from these sources show
-- without an editor's review; an admin can still hide any item. Only the headline, link and dates are kept.
update sources set enabled = false where name = 'GDELT: advertising and marketing news';
update signals set editorial_state = 'hidden' where source_id in (select id from sources where name = 'GDELT: advertising and marketing news');
update trends set editorial_state = 'hidden' where id in (select ts.trend_id from trend_signals ts join signals g on g.id = ts.signal_id join sources s on s.id = g.source_id where s.name = 'GDELT: advertising and marketing news');
insert into sources(organization_id, kind, name, config_public, enabled, refresh_minutes)
select o.id, v.kind, v.name, v.config::jsonb, true, v.mins from organizations o, (values
  ('gdelt', 'News search: Social media platforms', '{"query":"(\"social media\" OR tiktok OR instagram OR snapchat OR \"influencer marketing\" OR \"youtube shorts\") sourcelang:english","categoryHints":["Social media","Social","Creative","Media"],"titleTerms":["tiktok","instagram","snapchat","youtube","social media","influencer","influencers","creator","creators","reels","threads","linkedin","whatsapp","facebook","meta","pinterest","twitch","viral"],"autoApprove":true}', 360),
  ('gdelt', 'News search: Branding and campaigns', '{"query":"(\"ad campaign\" OR \"advertising campaign\" OR \"brand campaign\" OR rebrand OR \"brand identity\" OR \"creative agency\") sourcelang:english","categoryHints":["Branding","Creative","Strategy","PR"],"titleTerms":["campaign","campaigns","rebrand","rebrands","rebranding","brand","brands","branding","advert","adverts","advertising","commercial","slogan","logo","agency","ad"],"autoApprove":true}', 360),
  ('gdelt', 'News search: OOH and digital OOH', '{"query":"(billboard OR billboards OR \"out of home\" OR \"outdoor advertising\" OR \"digital signage\" OR dooh) sourcelang:english","categoryHints":["OOH","Media"],"titleTerms":["billboard","billboards","out of home","ooh","dooh","outdoor advertising","digital signage","signage","hoarding","hoardings"],"autoApprove":true}', 360),
  ('gdelt', 'News search: Paid media and lead generation', '{"query":"(\"lead generation\" OR \"digital marketing\" OR \"performance marketing\" OR \"paid social\" OR \"google ads\" OR \"programmatic advertising\" OR \"retail media\") sourcelang:english","categoryHints":["Paid media","Media","Strategy"],"titleTerms":["marketing","marketers","lead generation","leads","ads","programmatic","retail media","ad spend","adspend","seo","ecommerce","martech","adtech","advertisers"],"autoApprove":true}', 360),
  ('gdelt', 'News search: AI in marketing and creative', '{"query":"(\"generative ai\" OR \"ai generated\" OR \"artificial intelligence\") (advertising OR marketing OR \"social media\" OR branding) sourcelang:english","categoryHints":["AI in marketing","Creative","Strategy","Production"],"titleTerms":["ai","artificial intelligence","generative","chatgpt","openai","gemini","deepfake","deepfakes"],"autoApprove":true}', 360),
  ('gdelt', 'News search: Gulf marketing and media', '{"query":"(advertising OR marketing OR \"social media\" OR branding OR billboard) (sourcecountry:qatar OR sourcecountry:saudiarabia OR sourcecountry:unitedarabemirates OR sourcecountry:kuwait OR sourcecountry:bahrain OR sourcecountry:oman)","categoryHints":["Gulf","Strategy","Media","Client Service"],"titleTerms":["advertising","marketing","social media","brand","brands","branding","campaign","billboard","influencer","influencers","tiktok","instagram","snapchat","retail","ecommerce","media","تسويق","إعلان","إعلانات"],"autoApprove":true}', 360),
  ('rss', 'Social Media Today', '{"feedUrl":"https://www.socialmediatoday.com/feeds/news/","allow":["socialmediatoday.com"],"categoryHints":["Social media","Social","Creative","Media"],"autoApprove":true}', 180),
  ('rss', 'Hootsuite blog', '{"feedUrl":"https://blog.hootsuite.com/feed/","allow":["hootsuite.com"],"categoryHints":["Social media","Social"],"autoApprove":true}', 180),
  ('rss', 'Social Media Examiner', '{"feedUrl":"https://www.socialmediaexaminer.com/feed/","allow":["socialmediaexaminer.com"],"categoryHints":["Social media","Social","Creative"],"autoApprove":true}', 180),
  ('rss', 'Marketing Dive', '{"feedUrl":"https://www.marketingdive.com/feeds/news/","allow":["marketingdive.com"],"categoryHints":["Branding","Strategy","Creative","Media"],"autoApprove":true}', 180),
  ('rss', 'Adweek', '{"feedUrl":"https://www.adweek.com/feed/","allow":["adweek.com"],"categoryHints":["Branding","Creative","Media","Strategy"],"autoApprove":true}', 180),
  ('rss', 'Digiday', '{"feedUrl":"https://digiday.com/feed/","allow":["digiday.com"],"categoryHints":["Paid media","Media","Strategy"],"autoApprove":true}', 180),
  ('rss', 'OOH Today', '{"feedUrl":"https://oohtoday.com/feed/","allow":["oohtoday.com"],"categoryHints":["OOH","Media"],"autoApprove":true}', 180),
  ('rss', 'Campaign Middle East', '{"feedUrl":"https://campaignme.com/feed/","allow":["campaignme.com"],"categoryHints":["Gulf","Creative","Strategy","Media","PR"],"autoApprove":true,"publisherCountry":"United Arab Emirates"}', 180),
  ('rss', 'Communicate', '{"feedUrl":"https://communicateonline.me/feed/","allow":["communicateonline.me"],"categoryHints":["Gulf","Strategy","Media","PR"],"autoApprove":true,"publisherCountry":"United Arab Emirates"}', 180)
) as v(kind, name, config, mins) where o.slug = 'publicis'
on conflict (organization_id, name) do update set config_public = excluded.config_public, enabled = true, refresh_minutes = excluded.refresh_minutes;
